var DATA = {"shape": "SELECT by customer_id ordered by created_at", "chosen": "Covering index (customer_id, created_at)", "alts": "index-scan:45|full-scan:800|bitmap:120", "model": "B-tree depth + page reads"};
console.log("Query shape: " + DATA.shape);
console.log("Cost model: " + DATA.model);
var paths = [{ name: DATA.chosen, cost: 10 }];
// parse alternatives like "index-scan:25|full-scan:120"
DATA.alts.split("|").forEach(function (a) {
  var p = a.split(":").map(function (s) { return s.trim(); });
  if (p.length === 2) paths.push({ name: p[0], cost: parseFloat(p[1]) });
});
paths.sort(function (a, b) { return a.cost - b.cost; });
console.log("Candidate paths by cost:");
paths.forEach(function (p) { console.log("  " + p.name + " — cost " + p.cost + (p.name === DATA.chosen ? "  <-- chosen" : "")); });
var best = paths[0];
console.log("RESULT: cheapest path is '" + best.name + "' at cost " + best.cost + (best.name === DATA.chosen ? " (matches plan)" : " (plan differs — investigate)") + ".");

